import strings

func text_of(raw: bytes) -> str fails str:
    return try strings.decode(raw)

func main() -> int:
    mut encoded = strings.encode("h\u00e9llo")
    if len(encoded) != 6:
        return 1
    match text_of(encoded):
        case Ok(value):
            if value != "h\u00e9llo":
                return 2
        case Err(message):
            return 0 - strings.char_count(message)
    match text_of(b"\xff"):
        case Ok(other):
            return 0 - strings.char_count(other)
        case Err(message):
            return len(encoded)

