import bytes

func main() -> int:
    mut record = b"GET /index.html"
    if not bytes.starts_with(record, b"GET "):
        return 1
    if bytes.ends_with(record, b".css"):
        return 2
    if bytes.find(record, b"/index") != 4 or bytes.find(record, b"?query") != -1:
        return 3
    if 47 not in record or b"html" not in record:
        return 4
    if record == b"GET /" or record != b"GET /index.html":
        return 5
    if b"" not in record or bytes.find(record, b"") != 0:
        return 6
    return len(record)

import hex
import strings

func parse(digits: str) -> bytes fails str:
    return try bytes.fromhex(digits)

func main() -> int:
    mut raw = b"\x0f\xa0"
    if hex.encode(raw) != "0fa0":
        return 1
    if strings.char_count(hex.encode(b"")) != 0:
        return 2
    match parse("0fa0"):
        case Ok(value):
            if value != raw:
                return 3
        case Err(message):
            return 0 - strings.char_count(message)
    match parse("0f0"):
        case Ok(value):
            return 0 - len(value)
        case Err(message):
            return strings.char_count(message)

import bytes

func main() -> int:
    mut line = b"name,age,city"
    mut fields = bytes.split(line, b",")
    if len(fields) != 3 or fields[1] != b"age":
        return 1
    if bytes.join(fields, b",") != line:
        return 2
    mut edges = bytes.split(b",a,", b",")
    if len(edges) != 3 or len(edges[0]) != 0 or len(edges[2]) != 0:
        return 3
    mut widths = 0
    for field in fields:
        widths += len(field)
    return widths
